FILE *Locate_File (filename, mode)
char *filename, *mode;
  {
  FILE *f;
  int i;
  char pathname[FILE_NAME_LENGTH];

  /* Check the current directory first. */
  if ((f = fopen (filename, mode)) != NULL)
